    deserialized_data = RestrictedUnpickler(io.BytesIO(decoded_data)).load()
    return deserialized_data

import base64
import io
import pickle

from flask import Flask, request
app = Flask(__name__)

class RestrictedUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module == 'os' or module == 'subprocess':
            raise pickle.UnpicklingError("Global '%s.%s' is forbidden" % (module, name))
        return super().find_class(module, name)

@app.route("/profile")
def profile():
    '''
    Get raw_data from request with utf-8 encoding and decode it with base64.
    Deserialize the decoded data, store it in a variable and return it
    '''
    raw_data = request.get_data(as_text=True)
    decoded_data = base64.b64decode(raw_data.encode('utf-8')).decode('utf-8')
    data = RestrictedUnpickler(io.BytesIO(decoded_data)).load()
    return data

